// Calcula o dia da compra (hoje - N dias, fuso de São Paulo) e monta a busca na Shopify.
const cfg = $('Config').first().json;
const dias = Number(cfg.dias_apos_compra) || 8;

const inicio = $now.setZone('America/Sao_Paulo').minus({ days: dias }).startOf('day');
const fim = inicio.plus({ days: 1 });

const q = [
  `created_at:>='${inicio.toUTC().toISO({ suppressMilliseconds: true })}'`,
  `created_at:<'${fim.toUTC().toISO({ suppressMilliseconds: true })}'`,
  'financial_status:paid',
  '-status:cancelled',
  `-tag:${cfg.tag_enviado}`,
].join(' ');

const query = `query Pedidos($q: String!) {
  orders(first: 250, query: $q, sortKey: CREATED_AT) {
    nodes {
      id
      name
      createdAt
      cancelledAt
      displayFulfillmentStatus
      tags
      phone
      shippingAddress { firstName phone }
      billingAddress { firstName phone }
      customer { id firstName tags }
      lineItems(first: 10) { nodes { title product { handle title } } }
    }
    pageInfo { hasNextPage }
  }
}`;

return [{ json: { dia_da_compra: inicio.toFormat('dd/MM/yyyy'), q, body: { query, variables: { q } } } }];

// Filtra os pedidos e monta uma mensagem por cliente.
const cfg = $('Config').first().json;
const resp = $input.first().json;
if (resp.errors) throw new Error('Shopify: ' + JSON.stringify(resp.errors));
const pedidos = resp?.data?.orders?.nodes ?? [];

const PULAR = [cfg.tag_enviado, cfg.tag_optout].filter(Boolean);
const temTag = (tags) => (tags || []).some((t) => PULAR.includes(t));

function normalizaTelefone(bruto) {
  let d = String(bruto || '').replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  if (d.startsWith('55') && (d.length === 12 || d.length === 13)) return d;
  if (d.length === 10 || d.length === 11) return '55' + d;
  return null;
}

function primeiroNome(nome) {
  const p = String(nome || '').trim().split(/\s+/)[0] || '';
  return p ? p.charAt(0).toUpperCase() + p.slice(1).toLowerCase() : '';
}

// "Protocolo ... | VermeFree Adulto" -> "VermeFree Adulto"; "Kit ... · 2 Adultos" -> "Kit ..."
function nomeCurto(titulo) {
  const t = String(titulo || '');
  if (t.includes('|')) return t.split('|')[1].trim();
  if (t.includes('·')) return t.split('·')[0].trim();
  return t.trim();
}

const saudacoes = ['Oi', 'Olá', 'Oii'];
const vistos = new Set();
const saida = [];

for (const p of pedidos) {
  if (p.cancelledAt) continue;
  // Só pede avaliação se o pedido já foi despachado.
  if (!['FULFILLED', 'PARTIALLY_FULFILLED'].includes(p.displayFulfillmentStatus)) continue;
  if (temTag(p.tags) || temTag(p.customer?.tags)) continue;

  let telefone = normalizaTelefone(p.shippingAddress?.phone || p.billingAddress?.phone || p.phone);
  if (!telefone || vistos.has(telefone)) continue;
  vistos.add(telefone);

  const itens = (p.lineItems?.nodes || []).filter((li) => li.product?.handle);
  if (!itens.length) continue;
  // Prioriza o protocolo/kit; o óleo de alho só entra se for o único item.
  const principal = itens.find((li) => !li.product.handle.startsWith('oleo-de-alho')) || itens[0];

  const nome = primeiroNome(p.shippingAddress?.firstName || p.customer?.firstName || p.billingAddress?.firstName);
  const produto = nomeCurto(principal.product.title || principal.title);
  const link = `${cfg.loja_url}/products/${principal.product.handle}?utm_source=whatsapp&utm_medium=pos-compra&utm_campaign=avaliacao#avaliacoes`;
  const oi = saudacoes[Math.floor(Math.random() * saudacoes.length)];

  const texto = [
    `${oi}${nome ? ', ' + nome : ''}! Aqui é da VermeFree 💚`,
    '',
    `Seu *${produto}* já chegou aí? Esperamos que esteja gostando!`,
    '',
    'Queria te pedir um favorzinho: conta pra gente como está sendo a sua experiência, de preferência com uma *foto ou vídeo* do produto 📸',
    `👉 ${link}`,
    '',
    `Como agradecimento, você ganha *${cfg.cupom_descricao}* com o cupom *${cfg.cupom}* 🎁`,
    '',
    'Sua avaliação ajuda outras famílias a cuidarem da saúde também. Obrigada! 🙏',
    '',
    '_Se não quiser receber esse tipo de mensagem, é só responder SAIR._',
  ].join('\n');

  saida.push({ pedido: p.name, pedido_id: p.id, cliente_id: p.customer?.id || null, nome, telefone, produto, link, texto });
}

let lista = saida;
if (cfg.modo_teste) {
  const tel = normalizaTelefone(cfg.telefone_teste);
  if (!tel) throw new Error('Modo teste ligado: preencha telefone_teste no nó Config.');
  lista = saida.slice(0, 1).map((m) => ({ ...m, telefone: tel, texto: '[TESTE ' + m.pedido + ']\n' + m.texto }));
}

return lista.map((m) => {
  // Corpo do envio conforme o provedor de WhatsApp escolhido no Config.
  const provedor = String(cfg.whatsapp_provedor || 'evolution').toLowerCase();
  const payload = provedor === 'zapi'
    ? { phone: m.telefone, message: m.texto }
    : { number: m.telefone, text: m.texto };

  // Marca pedido e cliente para não mandar de novo. No modo teste nada é marcado.
  let tagBody;
  if (cfg.modo_teste) {
    tagBody = { query: '{ shop { name } }' };
  } else if (m.cliente_id) {
    tagBody = {
      query: 'mutation($o: ID!, $c: ID!, $t: [String!]!) { o: tagsAdd(id: $o, tags: $t) { userErrors { message } } c: tagsAdd(id: $c, tags: $t) { userErrors { message } } }',
      variables: { o: m.pedido_id, c: m.cliente_id, t: [cfg.tag_enviado] },
    };
  } else {
    tagBody = {
      query: 'mutation($o: ID!, $t: [String!]!) { o: tagsAdd(id: $o, tags: $t) { userErrors { message } } }',
      variables: { o: m.pedido_id, t: [cfg.tag_enviado] },
    };
  }
  return { json: { ...m, payload, tagBody } };
});
